 if(phase==5){Capture("Candle_"+frame.ToString("00"),900,700);frame++;if(frame<12){next=EditorApplication.timeSinceStartup+.1;return;}cam.transform.position=cameraPosition;cam.transform.rotation=cameraRotation;cam.fieldOfView=42;CheckAndRestore();EditorApplication.isPlaying=false;phase=9;return;}
 }catch(Exception e){Fail(e);}}
 static void CheckAndRestore(){if((RenderingLayerMask.GetDefinedRenderingLayersCombinedMaskValue()&ArenaCombatLook.CharacterMask)==0)throw new Exception("Character layer is not defined in the renderer settings");var renderers=actors.Player.Root.GetComponentsInChildren<Renderer>().Where(r=>!(r is ParticleSystemRenderer)).ToArray();if(renderers.Length==0||renderers.Any(r=>(r.renderingLayerMask&ArenaCombatLook.CharacterMask)==0))throw new Exception("Character lighting mask missing");var environment=look.transform.parent.GetComponentsInChildren<MeshRenderer>().Where(r=>!r.transform.IsChildOf(actors.transform));if(environment.Any(r=>(r.renderingLayerMask&ArenaCombatLook.CharacterMask)!=0))throw new Exception("Character lighting leaked into scenery");if(candleSystems.Length==0||candleSystems.Any(p=>p.main.maxParticles>32||p.GetComponent<Renderer>().shadowCastingMode!=ShadowCastingMode.Off))throw new Exception("Candle particle budget invalid");int particles=candleSystems.Sum(p=>p.particleCount);if(particles==0)throw new Exception("Candle particles did not animate");var lights=look.characterLights;if(lights.Any(l=>l.shadows!=LightShadows.None||l.GetUniversalAdditionalLightData().renderingLayers.value!=ArenaCombatLook.CharacterMask))throw new Exception("Character light contract invalid");look.enabled=false;if(cam.GetUniversalAdditionalCameraData().renderPostProcessing)throw new Exception("Preview camera postprocessing did not restore");if(renderers.Any(r=>(r.renderingLayerMask&ArenaCombatLook.CharacterMask)!=0))throw new Exception("Character layers did not restore");File.WriteAllText(Work+"/play_verification.txt","PASS real assembled player + Monteverdi avatars\nPASS actual FightFireballVisual and FighterAuraFx\nPASS character-only rendering layers, restored on disable\nPASS two shadowless character lights\nCandle holders="+candleSystems.Length+"; active particles="+particles+"; max32 per holder, no added flame lights\nLightmaps="+LightmapSettings.lightmaps.Length+"; probes="+(LightmapSettings.lightProbes?LightmapSettings.lightProbes.count:0)+"\nNo SSAO, motion blur, depth of field or chromatic aberration added. Mobile GPU performance not measured.");}
 static void Fail(Exception e){File.WriteAllText(Work+"/error.txt",e.ToString());Debug.LogException(e);EditorApplication.update-=Tick;if(EditorApplication.isPlaying)EditorApplication.isPlaying=false;EditorSettings.enterPlayModeOptionsEnabled=oldPlayEnabled;EditorSettings.enterPlayModeOptions=oldPlayOptions;EditorApplication.Exit(1);}
